const FEATURE_INDEX = Object.fromEntries(
  DATA.featureCols.map((f, i) => [f, i]),
);
const CONDITIONS = ["Sepsis", "ARF", "Cardiac", "AKI", "Coagulopathy"];

/* ---------- design tokens ---------- */
const COLORS = {
  bg: "#0a0d12",
  panel: "#11161d",
  panel2: "#161d26",
  panel3: "#1b232e",
  border: "#232b36",
  borderLight: "#2e3947",
  text: "#e7ecf2",
  textDim: "#8b98a8",
  textFaint: "#5b6a7a",
  mono: "'IBM Plex Mono', 'JetBrains Mono', monospace",
  sans: "'Inter', system-ui, sans-serif",
  green: "#34d399",
  greenDim: "#1a4a3a",
  amber: "#fbbf24",
  amberDim: "#4a3a1a",
  red: "#f87171",
  redDim: "#4a1e1e",
  blue: "#60a5fa",
  blueDim: "#1a324a",
  violet: "#a78bfa",
  violetDim: "#332a4a",
  cyan: "#22d3ee",
};

const CONDITION_META = {
  Sepsis: { color: COLORS.red, icon: Stethoscope },
  ARF: { color: COLORS.cyan, icon: Wind },
  Cardiac: { color: COLORS.violet, icon: Zap },
  AKI: { color: COLORS.amber, icon: Droplet },
  Coagulopathy: { color: "#f472b6", icon: Bug },
};

function riskBand(r) {
  if (r >= 0.8)
    return { label: "Critical", color: COLORS.red, dim: COLORS.redDim };
  if (r >= 0.6)
    return { label: "High", color: COLORS.amber, dim: COLORS.amberDim };
  return { label: "Normal", color: COLORS.green, dim: COLORS.greenDim };
}

/* Live what-if simulator: recomputes with the DISTILLED LINEAR SURROGATE
   (not the real 600-tree XGBoost — too heavy to ship client-side). Only the
   ~10 "right now" vitals are slider-adjustable; the 174 window-summary
   features (24h mean/std/min/max/trend) stay fixed at observed history,
   since moving a slider doesn't rewrite the past. Derived single-hour
   features (ShockIndex, PulsePressure, qSOFA) are recomputed from the
   adjusted vitals so the simulation stays physiologically consistent. */
function simulateRisk(cond, baselineArray, overrides) {
  const f = baselineArray.slice();
  const set = (name, val) => {
    f[FEATURE_INDEX[name]] = val;
  };
  const get = (name) => f[FEATURE_INDEX[name]];

  for (const [k, v] of Object.entries(overrides)) set(k, v);

  const hr = get("HR"),
    sbp = get("SBP"),
    dbp = get("DBP"),
    resp = get("Resp"),
    map_ = get("MAP");
  set("ShockIndex", sbp ? hr / sbp : get("ShockIndex"));
  set("PulsePressure", sbp - dbp);
  set(
    "qSOFA_proxy",
    (resp >= 22 ? 1 : 0) + (sbp <= 100 ? 1 : 0) + (map_ < 65 ? 1 : 0),
  );

  const s = DATA.surrogates[cond];
  let z = s.intercept;
  for (let i = 0; i < f.length; i++) {
    const val = f[i] ?? s.mean[i];
    z += s.coef[i] * ((val - s.mean[i]) / (s.std[i] || 1));
  }
  return 1 / (1 + Math.exp(-z));
}

function cosineSim(a, b) {
  let dot = 0,
    na = 0,
    nb = 0;
  for (let i = 0; i < a.length; i++) {
    dot += a[i] * b[i];
    na += a[i] * a[i];
    nb += b[i] * b[i];
  }
  return dot / (Math.sqrt(na) * Math.sqrt(nb) + 1e-9);
}

function downloadCSV(filename, rows) {
  const csv = rows
    .map((r) => r.map((c) => `"${String(c).replace(/"/g, '""')}"`).join(","))
    .join("\n");
  const blob = new Blob([csv], { type: "text/csv" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

