/* ================= similar patients ================= */

function SimilarPatients({ patient, onSelect }) {
  const cohort = DATA.cohortIndex;
  const idx = cohort.patientId.indexOf(patient.patientId);
  if (idx === -1) return null;
  const myLatent = cohort.latent[idx];
  const sims = cohort.patientId
    .map((pid, i) =>
      pid === patient.patientId
        ? null
        : { pid, sim: cosineSim(myLatent, cohort.latent[i]), i },
    )
    .filter(Boolean)
    .sort((a, b) => b.sim - a.sim)
    .slice(0, 5);

  return (
    <div
      style={{
        background: COLORS.panel2,
        border: `1px solid ${COLORS.border}`,
        borderRadius: 12,
        padding: 14,
      }}
    >
      <SectionLabel
        icon={<Users2 size={13} />}
        text="Similar Patients (cosine similarity, 215-feature space)"
      />
      <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
        {sims.map(({ pid, sim, i }) => {
          const hasDetail = cohort.hasFullDetail[i];
          return (
            <div
              key={pid}
              onClick={() => hasDetail && onSelect(pid)}
              style={{
                display: "flex",
                alignItems: "center",
                justifyContent: "space-between",
                padding: "7px 10px",
                borderRadius: 8,
                background: COLORS.panel3,
                cursor: hasDetail ? "pointer" : "default",
                opacity: hasDetail ? 1 : 0.55,
              }}
            >
              <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                <span
                  style={{
                    fontFamily: COLORS.mono,
                    fontSize: 12,
                    color: COLORS.text,
                  }}
                >
                  {pid}
                </span>
                <span style={{ fontSize: 10, color: COLORS.textFaint }}>
                  {cohort.age[i]}y {cohort.gender[i]}
                </span>
                {!hasDetail && (
                  <span style={{ fontSize: 9, color: COLORS.textFaint }}>
                    (index only)
                  </span>
                )}
              </div>
              <div style={{ display: "flex", gap: 4, alignItems: "center" }}>
                {CONDITIONS.map(
                  (c) =>
                    cohort[`ever${c}`][i] && (
                      <span
                        key={c}
                        style={{
                          fontSize: 9,
                          padding: "1px 5px",
                          borderRadius: 4,
                          color: CONDITION_META[c].color,
                          border: `1px solid ${CONDITION_META[c].color}55`,
                        }}
                      >
                        {c.slice(0, 4)}
                      </span>
                    ),
                )}
                <span
                  style={{
                    fontFamily: COLORS.mono,
                    fontSize: 11,
                    color: COLORS.textDim,
                    marginLeft: 4,
                  }}
                >
                  {(sim * 100).toFixed(0)}%
                </span>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

/* ================= simulation ================= */

function SimPanel({ patient, condition, onRunAudit }) {
  const base = patient.baselineFeatures;
  const meta = CONDITION_META[condition];
  const fidelity = DATA.surrogates[condition].fidelity;
  const [scenarios, setScenarios] = useState([{ id: 1, overrides: {} }]);
  const [apiRisk, setApiRisk] = useState(null);
  const [apiModelInfo, setApiModelInfo] = useState(null);
  const [apiLoading, setApiLoading] = useState(false);
  const [apiError, setApiError] = useState("");

  const runAzurePrediction = async () => {
    setApiLoading(true);
    setApiError("");
    setApiRisk(null);

    try {
      const features = Object.fromEntries(
        DATA.featureCols.map((name, i) => [
          name,
          active.overrides[name] ?? base[i] ?? 0,
        ]),
      );

      const response = await fetch(`${API_URL}/predict`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          condition,
          horizon: 6,
          features,
          explain: false,
        }),
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.detail || "Azure prediction failed");
      }

      setApiRisk(data.risk);
      setApiModelInfo({
        task: data.task,
        modelVersion: data.model_version,
      });
    } catch (error) {
      setApiError(error.message || "Could not connect to Azure");
    } finally {
      setApiLoading(false);
    }
  };

  const baselineRisk = useMemo(
    () => simulateRisk(condition, base, {}),
    [condition, base],
  );
  const results = scenarios.map((s) => ({
    ...s,
    risk: simulateRisk(condition, base, s.overrides),
  }));

  const addScenario = () =>
    scenarios.length < 3 &&
    setScenarios((s) => [...s, { id: Date.now(), overrides: {} }]);
  const removeScenario = (id) =>
    setScenarios((s) => s.filter((x) => x.id !== id));
  const updateOverride = (id, key, val) =>
    setScenarios((s) =>
      s.map((x) =>
        x.id === id ? { ...x, overrides: { ...x.overrides, [key]: val } } : x,
      ),
    );
  const resetScenario = (id) =>
    setScenarios((s) =>
      s.map((x) => (x.id === id ? { ...x, overrides: {} } : x)),
    );

  const [activeTab, setActiveTab] = useState(scenarios[0].id);
  const active = scenarios.find((s) => s.id === activeTab) || scenarios[0];
  const activeResult = results.find((r) => r.id === active.id);
  const activeIdx = scenarios.indexOf(active);

  const compareData = [
    { name: "Baseline", risk: baselineRisk, fill: COLORS.textFaint },
    ...results.map((r, i) => ({
      name: `Scenario ${i + 1}`,
      risk: r.risk,
      fill: SCENARIO_COLORS[i % 3],
    })),
  ];

  return (
    <div
      style={{
        background: COLORS.panel2,
        border: `1px solid ${COLORS.border}`,
        borderRadius: 12,
        padding: 16,
      }}
    >
      <div
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          marginBottom: 8,
        }}
      >
        <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
          <Sliders size={15} color={meta.color} />
          <span style={{ fontSize: 13, fontWeight: 600, color: COLORS.text }}>
            What-if Simulation — {condition}
          </span>
        </div>
        {scenarios.length < 3 && (
          <GhostButton onClick={addScenario} icon={<Plus size={11} />}>
            Add scenario
          </GhostButton>
        )}
      </div>

      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: 6,
          fontSize: 10.5,
          color: COLORS.textFaint,
          background: COLORS.panel3,
          borderRadius: 7,
          padding: "6px 10px",
          marginBottom: 12,
        }}
      >
        <CheckCircle2 size={12} color={COLORS.green} />
        Simulator is a linear model distilled from the production XGBoost —
        fidelity check: Pearson r={fidelity.pearson_r}, agreement{" "}
        {(fidelity["binary_agreement_rate_at_0.5"] * 100).toFixed(0)}% at 0.5
        threshold. Real explanation (SHAP chart above) uses exact TreeExplainer,
        not this surrogate.
      </div>

      <div
        style={{ display: "flex", gap: 6, marginBottom: 12, flexWrap: "wrap" }}
      >
        {scenarios.map((s, i) => (
          <div
            key={s.id}
            onClick={() => setActiveTab(s.id)}
            style={{
              display: "flex",
              alignItems: "center",
              gap: 6,
              cursor: "pointer",
              padding: "5px 10px",
              borderRadius: 7,
              fontSize: 11.5,
              fontFamily: COLORS.mono,
              background: activeTab === s.id ? COLORS.panel3 : "transparent",
              border: `1px solid ${activeTab === s.id ? SCENARIO_COLORS[i % 3] : COLORS.border}`,
              color:
                activeTab === s.id ? SCENARIO_COLORS[i % 3] : COLORS.textDim,
            }}
          >
            Scenario {i + 1}
            {scenarios.length > 1 && (
              <X
                size={11}
                onClick={(e) => {
                  e.stopPropagation();
                  removeScenario(s.id);
                }}
              />
            )}
          </div>
        ))}
      </div>

      <div
        style={{
          display: "grid",
          gridTemplateColumns: "1fr 1fr",
          gap: "10px 20px",
          marginBottom: 16,
        }}
      >
        {SLIDER_DEFS.map((s) => {
          const val =
            active.overrides[s.key] ?? base[FEATURE_INDEX[s.key]] ?? 0;
          return (
            <div key={s.key}>
              <div
                style={{
                  display: "flex",
                  justifyContent: "space-between",
                  fontSize: 11,
                  marginBottom: 3,
                }}
              >
                <span style={{ color: COLORS.textDim }}>{s.label}</span>
                <span
                  style={{
                    color:
                      active.overrides[s.key] !== undefined
                        ? SCENARIO_COLORS[activeIdx % 3]
                        : COLORS.textFaint,
                    fontFamily: COLORS.mono,
                  }}
                >
                  {val.toFixed(s.step < 1 ? 1 : 0)} {s.unit}
                </span>
              </div>
              <input
                type="range"
                min={s.min}
                max={s.max}
                step={s.step}
                value={val}
                onChange={(e) =>
                  updateOverride(active.id, s.key, parseFloat(e.target.value))
                }
                style={{
                  width: "100%",
                  accentColor: SCENARIO_COLORS[activeIdx % 3],
                }}
              />
            </div>
          );
        })}
      </div>

      <div style={{ display: "flex", gap: 8, marginBottom: 14 }}>
        <GhostButton
          onClick={() => resetScenario(active.id)}
          icon={<RotateCcw size={11} />}
        >
          Reset scenario
        </GhostButton>
        <GhostButton onClick={runAzurePrediction} disabled={apiLoading}>
          {apiLoading ? "Calling Azure..." : "Run Azure Prediction"}
        </GhostButton>
        <GhostButton
          onClick={() =>
            onRunAudit(condition, active.overrides, activeResult.risk)
          }
          icon={<ScrollText size={11} />}
        >
          Log to audit trail
        </GhostButton>
      </div>

      {apiRisk !== null && (
        <div
          style={{
            marginBottom: 14,
            padding: 12,
            borderRadius: 8,
            background: COLORS.panel3,
            color: COLORS.text,
            fontSize: 12,
          }}
        >
          <strong>Azure Model Prediction:</strong> {(apiRisk * 100).toFixed(2)}%
          risk
          {apiModelInfo && (
            <div style={{ color: COLORS.textFaint, marginTop: 4 }}>
              Task: {apiModelInfo.task} · Model: {apiModelInfo.modelVersion}
            </div>
          )}
          <div style={{ color: COLORS.textFaint, marginTop: 4 }}>
            Model response from your deployed FastAPI backend · 6-hour horizon
          </div>
        </div>
      )}

      {apiError && (
        <div style={{ color: "#ef4444", fontSize: 12, marginBottom: 12 }}>
          Azure API error: {apiError}
        </div>
      )}

      <ResponsiveContainer width="100%" height={110}>
        <BarChart
          data={compareData}
          margin={{ top: 4, right: 12, left: -20, bottom: 0 }}
        >
          <CartesianGrid
            stroke={COLORS.border}
            strokeDasharray="3 3"
            vertical={false}
          />
          <XAxis
            dataKey="name"
            tick={{
              fill: COLORS.textFaint,
              fontSize: 10,
              fontFamily: COLORS.sans,
            }}
          />
          <YAxis
            domain={[0, 1]}
            tick={{ fill: COLORS.textFaint, fontSize: 10 }}
            width={30}
          />
          <Tooltip
            content={({ active, payload }) =>
              !active || !payload?.length ? null : (
                <div
                  style={{
                    background: COLORS.panel3,
                    border: `1px solid ${COLORS.borderLight}`,
                    borderRadius: 8,
                    padding: "6px 10px",
                    fontFamily: COLORS.mono,
                    fontSize: 12,
                    color: COLORS.text,
                  }}
                >
                  {(payload[0].value * 100).toFixed(1)}%
                </div>
              )
            }
          />
          <Bar dataKey="risk" radius={[4, 4, 0, 0]}>
            {compareData.map((d, i) => (
              <Cell key={i} fill={d.fill} />
            ))}
          </Bar>
        </BarChart>
      </ResponsiveContainer>
    </div>
  );
}

/* ================= patient detail ================= */

function PatientDetail({ patient, onRunAudit, onSelectPatient }) {
  const [condition, setCondition] = useState("Sepsis");
  const cond = patient.conditions[condition];
  const meta = CONDITION_META[condition];
  const lastIdx = patient.hourly.hour.length - 1;

  const exportCSV = () => {
    const rows = [
      ["hour", ...CONDITIONS.map((c) => `risk${c}`), ...DATA.displayVitals],
    ];
    patient.hourly.hour.forEach((h, i) => {
      rows.push([
        h,
        ...CONDITIONS.map((c) => patient.hourly[`risk${c}`][i]),
        ...DATA.displayVitals.map((v) => patient.hourly[v][i]),
      ]);
    });
    downloadCSV(`${patient.patientId}_digital_twin.csv`, rows);
  };

  return (
    <div style={{ padding: 24, overflowY: "auto", flex: 1 }}>
      <div
        style={{
          display: "flex",
          alignItems: "flex-start",
          justifyContent: "space-between",
          marginBottom: 14,
        }}
      >
        <div>
          <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
            <User size={18} color={COLORS.textDim} />
            <span
              style={{
                fontFamily: COLORS.mono,
                fontSize: 20,
                color: COLORS.text,
                fontWeight: 700,
              }}
            >
              {patient.patientId}
            </span>
            <RiskPill risk={patient.compositeRisk} />
            <span style={{ fontSize: 10, color: COLORS.textFaint }}>
              composite (max across conditions)
            </span>
          </div>
          <div
            style={{ fontSize: 12.5, color: COLORS.textFaint, marginTop: 4 }}
          >
            {patient.age}y {patient.gender} · ICU LOS {patient.losHours}h
            {CONDITIONS.map(
              (c) =>
                patient[`ever${c}`] && (
                  <span
                    key={c}
                    style={{ color: CONDITION_META[c].color, marginLeft: 8 }}
                  >
                    <ShieldAlert
                      size={11}
                      style={{ display: "inline", marginBottom: -1 }}
                    />{" "}
                    {c} (retrospective)
                  </span>
                ),
            )}
          </div>
        </div>
        <GhostButton onClick={exportCSV} icon={<Download size={12} />}>
          Export CSV
        </GhostButton>
      </div>

      <div
        style={{ display: "flex", gap: 8, marginBottom: 16, flexWrap: "wrap" }}
      >
        {CONDITIONS.map((c) => {
          const m = CONDITION_META[c];
          const Icon = m.icon;
          const active = condition === c;
          const r = patient.conditions[c].currentRisk6h;
          return (
            <button
              key={c}
              onClick={() => setCondition(c)}
              style={{
                display: "flex",
                alignItems: "center",
                gap: 8,
                cursor: "pointer",
                padding: "8px 14px",
                borderRadius: 10,
                background: active ? COLORS.panel2 : "transparent",
                border: `1px solid ${active ? m.color : COLORS.border}`,
              }}
            >
              <Icon size={14} color={m.color} />
              <span
                style={{
                  fontSize: 12.5,
                  color: active ? COLORS.text : COLORS.textDim,
                  fontWeight: 600,
                }}
              >
                {c}
              </span>
              <RiskPill risk={r} size="sm" />
            </button>
          );
        })}
      </div>

      <div
        style={{
          display: "flex",
          alignItems: "flex-start",
          gap: 10,
          background: riskBand(cond.currentRisk6h).dim,
          border: `1px solid ${riskBand(cond.currentRisk6h).color}33`,
          borderRadius: 10,
          padding: "10px 14px",
          marginBottom: 18,
        }}
      >
        <Info
          size={15}
          color={riskBand(cond.currentRisk6h).color}
          style={{ marginTop: 1, flexShrink: 0 }}
        />
        <div>
          <span style={{ fontSize: 12.5, color: COLORS.text, lineHeight: 1.5 }}>
            {cond.narrative}
          </span>
          <div
            style={{ fontSize: 10.5, color: COLORS.textFaint, marginTop: 4 }}
          >
            {DATA.conditionLabels[condition]} — peak{" "}
            {(cond.peakRisk * 100).toFixed(0)}% at hour {cond.peakHour} · 6h:{" "}
            {(cond.riskByHorizon["6h"] * 100).toFixed(0)}% · 12h:{" "}
            {(cond.riskByHorizon["12h"] * 100).toFixed(0)}% · 24h:{" "}
            {(cond.riskByHorizon["24h"] * 100).toFixed(0)}%
          </div>
        </div>
      </div>

      <div
        style={{ display: "flex", gap: 10, flexWrap: "wrap", marginBottom: 22 }}
      >
        {DATA.displayVitals.map((v) => (
          <VitalCard key={v} label={v} value={patient.hourly[v][lastIdx]} />
        ))}
      </div>

      <SectionLabel
        icon={<Activity size={13} />}
        text={`Risk Trajectory — ${condition} (XGBoost, 6h horizon)`}
      />
      <div
        style={{
          background: COLORS.panel2,
          border: `1px solid ${COLORS.border}`,
          borderRadius: 12,
          padding: "12px 8px 4px",
          marginBottom: 22,
        }}
      >
        <RiskTrajectoryChart
          hourly={patient.hourly}
          activeCondition={condition}
        />
      </div>

      <div
        style={{
          display: "grid",
          gridTemplateColumns: "1fr 1fr",
          gap: 16,
          marginBottom: 22,
        }}
      >
        <div>
          <SectionLabel
            icon={<FlaskConical size={13} />}
            text="Exact SHAP (TreeExplainer)"
          />
          <div
            style={{
              background: COLORS.panel2,
              border: `1px solid ${COLORS.border}`,
              borderRadius: 12,
              padding: 12,
            }}
          >
            <ShapChart topFeatures={cond.topFeatures} color={meta.color} />
          </div>
        </div>
        <div>
          <SectionLabel icon={<Users2 size={13} />} text="" />
          <SimilarPatients patient={patient} onSelect={onSelectPatient} />
        </div>
      </div>

      {/* ---- OOD Warning Banner ---- */}
      {patient.oodStatus && patient.oodStatus.status !== "in_distribution" && (
        <div
          style={{
            display: "flex",
            alignItems: "flex-start",
            gap: 10,
            background:
              patient.oodStatus.status === "extreme_ood"
                ? COLORS.redDim
                : COLORS.amberDim,
            border: `1px solid ${patient.oodStatus.status === "extreme_ood" ? COLORS.red : COLORS.amber}44`,
            borderRadius: 10,
            padding: "10px 14px",
            marginBottom: 18,
          }}
        >
          <AlertTriangle
            size={15}
            color={
              patient.oodStatus.status === "extreme_ood"
                ? COLORS.red
                : COLORS.amber
            }
            style={{ marginTop: 1, flexShrink: 0 }}
          />
          <div>
            <span
              style={{ fontSize: 12.5, color: COLORS.text, fontWeight: 600 }}
            >
              {patient.oodStatus.status === "extreme_ood"
                ? "Extreme Out-of-Distribution"
                : patient.oodStatus.status === "out_of_distribution"
                  ? "Out-of-Distribution Patient"
                  : "Borderline Distribution"}
            </span>
            <div style={{ fontSize: 11, color: COLORS.textDim, marginTop: 4 }}>
              Mahalanobis distance: {patient.oodStatus.mahalanobis_distance} —
              predictions may be less reliable.
              {patient.oodStatus.anomalous_features &&
                patient.oodStatus.anomalous_features.length > 0 && (
                  <span>
                    {" "}
                    Unusual features:{" "}
                    {patient.oodStatus.anomalous_features
                      .slice(0, 3)
                      .map((f) => `${f.feature} (z=${f.z_score})`)
                      .join(", ")}
                  </span>
                )}
            </div>
          </div>
        </div>
      )}

      {/* ---- IT-SHAP Temporal Attribution ---- */}
      {patient.itshap && patient.itshap[condition] && (
        <div style={{ marginBottom: 22 }}>
          <SectionLabel
            icon={<Activity size={13} />}
            text={`Temporal Attribution — ${condition} (IT-SHAP / LSTM)`}
          />
          <div
            style={{
              background: COLORS.panel2,
              border: `1px solid ${COLORS.border}`,
              borderRadius: 12,
              padding: 14,
            }}
          >
            <div
              style={{
                fontSize: 11,
                color: COLORS.textFaint,
                marginBottom: 10,
              }}
            >
              LSTM risk:{" "}
              {(patient.itshap[condition].lstm_risk * 100).toFixed(1)}% — shows
              which time steps and features the LSTM relied on most
            </div>
            {patient.itshap[condition].temporal_detail.map((td, i) => (
              <div
                key={i}
                style={{
                  display: "flex",
                  alignItems: "flex-start",
                  gap: 12,
                  padding: "8px 0",
                  borderBottom:
                    i < patient.itshap[condition].temporal_detail.length - 1
                      ? `1px solid ${COLORS.border}`
                      : "none",
                }}
              >
                <div
                  style={{
                    minWidth: 54,
                    textAlign: "center",
                    padding: "4px 8px",
                    background:
                      td.timestep_importance > 0
                        ? COLORS.redDim
                        : COLORS.greenDim,
                    borderRadius: 6,
                    fontSize: 11,
                    fontWeight: 600,
                    fontFamily: COLORS.mono,
                    color:
                      td.timestep_importance > 0 ? COLORS.red : COLORS.green,
                  }}
                >
                  {td.hour != null ? `h${td.hour}` : `t${td.timestep}`}
                </div>
                <div style={{ flex: 1 }}>
                  <div
                    style={{
                      fontSize: 11,
                      color: COLORS.textDim,
                      marginBottom: 4,
                    }}
                  >
                    Impact: {td.timestep_importance > 0 ? "+" : ""}
                    {(td.timestep_importance * 100).toFixed(1)}pp
                  </div>
                  <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
                    {td.features.slice(0, 4).map((f, fi) => (
                      <span
                        key={fi}
                        style={{
                          fontSize: 10,
                          padding: "2px 6px",
                          borderRadius: 4,
                          background: f.attribution > 0 ? "#4a1e1e" : "#1a4a3a",
                          color: f.attribution > 0 ? COLORS.red : COLORS.green,
                        }}
                      >
                        {DATA.featureLabels[f.feature] || f.feature}:{" "}
                        {f.attribution > 0 ? "+" : ""}
                        {(f.attribution * 100).toFixed(1)}pp
                      </span>
                    ))}
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* ---- Counterfactual Explanations ---- */}
      {patient.counterfactuals && patient.counterfactuals[condition] && (
        <div style={{ marginBottom: 22 }}>
          <SectionLabel
            icon={<GitCompare size={13} />}
            text={`What Could Change the Prediction — ${condition}`}
          />
          <div
            style={{
              background: COLORS.panel2,
              border: `1px solid ${COLORS.border}`,
              borderRadius: 12,
              padding: 14,
            }}
          >
            {(() => {
              const cf = patient.counterfactuals[condition];
              return (
                <>
                  <div
                    style={{
                      display: "flex",
                      alignItems: "center",
                      gap: 12,
                      marginBottom: 12,
                    }}
                  >
                    <div style={{ fontSize: 12, color: COLORS.textDim }}>
                      Current risk:{" "}
                      <span style={{ color: COLORS.red, fontWeight: 600 }}>
                        {(cf.original_risk * 100).toFixed(1)}%
                      </span>
                    </div>
                    <span style={{ color: COLORS.textFaint }}>→</span>
                    <div style={{ fontSize: 12, color: COLORS.textDim }}>
                      Projected:{" "}
                      <span
                        style={{
                          color: cf.target_achieved
                            ? COLORS.green
                            : COLORS.amber,
                          fontWeight: 600,
                        }}
                      >
                        {(cf.counterfactual_risk * 100).toFixed(1)}%
                      </span>
                    </div>
                    <span
                      style={{
                        fontSize: 10,
                        padding: "2px 8px",
                        borderRadius: 4,
                        background: cf.target_achieved
                          ? COLORS.greenDim
                          : COLORS.amberDim,
                        color: cf.target_achieved ? COLORS.green : COLORS.amber,
                      }}
                    >
                      {cf.target_achieved
                        ? "Target achieved"
                        : `−${(cf.risk_reduction * 100).toFixed(1)}pp`}
                    </span>
                  </div>
                  <div
                    style={{
                      fontSize: 10.5,
                      color: COLORS.textFaint,
                      marginBottom: 10,
                    }}
                  >
                    Smallest plausible changes to modifiable features (
                    {cf.n_features_changed} feature
                    {cf.n_features_changed > 1 ? "s" : ""}):
                  </div>
                  {cf.changes.map((ch, ci) => (
                    <div
                      key={ci}
                      style={{
                        display: "flex",
                        alignItems: "center",
                        gap: 10,
                        padding: "6px 0",
                        borderBottom:
                          ci < cf.changes.length - 1
                            ? `1px solid ${COLORS.border}`
                            : "none",
                      }}
                    >
                      <span
                        style={{
                          fontSize: 12,
                          color: COLORS.text,
                          minWidth: 120,
                          fontWeight: 500,
                        }}
                      >
                        {DATA.featureLabels[ch.feature] || ch.feature}
                      </span>
                      <span
                        style={{
                          fontSize: 11,
                          color: COLORS.textFaint,
                          fontFamily: COLORS.mono,
                        }}
                      >
                        {ch.current_value}
                      </span>
                      <span style={{ color: COLORS.textFaint }}>→</span>
                      <span
                        style={{
                          fontSize: 11,
                          fontFamily: COLORS.mono,
                          fontWeight: 600,
                          color: ch.change > 0 ? COLORS.green : COLORS.red,
                        }}
                      >
                        {ch.suggested_value}
                      </span>
                      <span style={{ fontSize: 10, color: COLORS.textFaint }}>
                        ({ch.change > 0 ? "+" : ""}
                        {ch.change})
                      </span>
                    </div>
                  ))}
                  <div
                    style={{
                      fontSize: 9.5,
                      color: COLORS.textFaint,
                      marginTop: 8,
                      fontStyle: "italic",
                    }}
                  >
                    Decision support only — shows feature changes associated
                    with lower predicted risk within training data bounds. Not a
                    treatment recommendation.
                  </div>
                </>
              );
            })()}
          </div>
        </div>
      )}

      <SectionLabel
        icon={<Sliders size={13} />}
        text="Scenario-Based Simulation"
      />
      {/* ---- Surrogate Fidelity Indicator ---- */}
      {patient.surrogateFidelity && patient.surrogateFidelity[condition] && (
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: 8,
            marginBottom: 8,
            padding: "6px 12px",
            borderRadius: 8,
            background:
              patient.surrogateFidelity[condition].reliability === "high"
                ? COLORS.greenDim
                : patient.surrogateFidelity[condition].reliability === "medium"
                  ? COLORS.blueDim
                  : patient.surrogateFidelity[condition].reliability === "low"
                    ? COLORS.amberDim
                    : COLORS.redDim,
          }}
        >
          {patient.surrogateFidelity[condition].reliability === "high" ? (
            <CheckCircle2 size={12} color={COLORS.green} />
          ) : (
            <AlertTriangle
              size={12}
              color={
                patient.surrogateFidelity[condition].reliability === "medium"
                  ? COLORS.blue
                  : patient.surrogateFidelity[condition].reliability === "low"
                    ? COLORS.amber
                    : COLORS.red
              }
            />
          )}
          <span style={{ fontSize: 10.5, color: COLORS.textDim }}>
            Simulator fidelity:{" "}
            <span
              style={{
                fontWeight: 600,
                color:
                  patient.surrogateFidelity[condition].reliability === "high"
                    ? COLORS.green
                    : patient.surrogateFidelity[condition].reliability ===
                        "medium"
                      ? COLORS.blue
                      : patient.surrogateFidelity[condition].reliability ===
                          "low"
                        ? COLORS.amber
                        : COLORS.red,
              }}
            >
              {patient.surrogateFidelity[condition].reliability}
            </span>{" "}
            (error:{" "}
            {(
              patient.surrogateFidelity[condition].absolute_error * 100
            ).toFixed(1)}
            pp, XGBoost:{" "}
            {(patient.surrogateFidelity[condition].xgb_risk * 100).toFixed(1)}%
            vs surrogate:{" "}
            {(
              patient.surrogateFidelity[condition].surrogate_risk * 100
            ).toFixed(1)}
            %)
          </span>
        </div>
      )}
      <SimPanel
        patient={patient}
        condition={condition}
        onRunAudit={onRunAudit}
      />
    </div>
  );
}

/* ================= cohort analytics ================= */

function CohortAnalyticsView() {
  const cohort = DATA.cohortIndex;
  const n = cohort.patientId.length;
  const counts = {};
  CONDITIONS.forEach((c) => {
    counts[c] = 0;
  });
  cohort.patientId.forEach((_, i) =>
    CONDITIONS.forEach((c) => {
      if (cohort[`ever${c}`][i]) counts[c]++;
    }),
  );
  const prevalenceData = CONDITIONS.map((c) => ({
    name: c,
    count: counts[c],
    pct: ((100 * counts[c]) / n).toFixed(1),
    fill: CONDITION_META[c].color,
  }));

  const metrics = DATA.modelMetrics;
  const comparison = DATA.modelComparison;
  const taskRows = Object.entries(metrics).filter(([k]) => !k.startsWith("_"));

  const [compareTask, setCompareTask] = useState("Sepsis_6h");
  const modelOrder = [
    "clinical_rule_qSOFA",
    "logistic_regression",
    "random_forest",
    "xgboost",
    "lstm_multitask_bilstm",
  ];
  const modelLabel = {
    clinical_rule_qSOFA: "Clinical rule",
    logistic_regression: "LogReg",
    random_forest: "Random Forest",
    xgboost: "XGBoost (production)",
    lstm_multitask_bilstm: "BiLSTM",
  };
  const cmp = comparison[compareTask];
  const cmpData = cmp
    ? modelOrder
        .filter((m) => cmp.results[m]?.AUROC != null)
        .map((m) => ({
          name: modelLabel[m],
          AUROC: cmp.results[m].AUROC,
          fill: m === "xgboost" ? COLORS.blue : COLORS.textFaint,
        }))
    : [];

  const exportCohort = () => {
    const rows = [
      ["patientId", "age", "gender", ...CONDITIONS.map((c) => `ever${c}`)],
    ];
    cohort.patientId.forEach((pid, i) =>
      rows.push([
        pid,
        cohort.age[i],
        cohort.gender[i],
        ...CONDITIONS.map((c) => cohort[`ever${c}`][i]),
      ]),
    );
    downloadCSV("cohort_index_export.csv", rows);
  };

  return (
    <div style={{ padding: 24, overflowY: "auto", flex: 1 }}>
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          marginBottom: 18,
        }}
      >
        <div>
          <div style={{ fontSize: 18, fontWeight: 700 }}>Cohort Analytics</div>
          <div style={{ fontSize: 12, color: COLORS.textFaint, marginTop: 2 }}>
            {n} {DATA.generatedFrom}
          </div>
        </div>
        <GhostButton onClick={exportCohort} icon={<Download size={12} />}>
          Export cohort CSV
        </GhostButton>
      </div>

      <SectionLabel
        icon={<BarChart3 size={13} />}
        text="Condition Prevalence in Cohort"
      />
      <div
        style={{
          background: COLORS.panel2,
          border: `1px solid ${COLORS.border}`,
          borderRadius: 12,
          padding: 16,
          marginBottom: 24,
        }}
      >
        <ResponsiveContainer width="100%" height={160}>
          <BarChart
            data={prevalenceData}
            margin={{ top: 4, right: 20, left: -10, bottom: 0 }}
          >
            <CartesianGrid
              stroke={COLORS.border}
              strokeDasharray="3 3"
              vertical={false}
            />
            <XAxis
              dataKey="name"
              tick={{ fill: COLORS.textDim, fontSize: 12 }}
            />
            <YAxis tick={{ fill: COLORS.textFaint, fontSize: 10 }} />
            <Tooltip
              content={({ active, payload }) => {
                if (!active || !payload?.length) return null;
                const d = payload[0].payload;
                return (
                  <div
                    style={{
                      background: COLORS.panel3,
                      border: `1px solid ${COLORS.borderLight}`,
                      borderRadius: 8,
                      padding: "6px 10px",
                      fontSize: 12,
                      color: COLORS.text,
                    }}
                  >
                    {d.name}: {d.count} patients ({d.pct}%)
                  </div>
                );
              }}
            />
            <Bar dataKey="count" radius={[6, 6, 0, 0]}>
              {prevalenceData.map((d, i) => (
                <Cell key={i} fill={d.fill} />
              ))}
            </Bar>
          </BarChart>
        </ResponsiveContainer>
      </div>

      <SectionLabel
        icon={<GitCompare size={13} />}
        text="Model Comparison — fair, information-matched (all models see the same 24h window)"
        right={
          <select
            value={compareTask}
            onChange={(e) => setCompareTask(e.target.value)}
            style={{
              background: COLORS.panel3,
              color: COLORS.text,
              border: `1px solid ${COLORS.border}`,
              borderRadius: 6,
              fontSize: 11,
              padding: "4px 8px",
              fontFamily: COLORS.mono,
            }}
          >
            {Object.keys(comparison)
              .filter((t) => !t.startsWith("_"))
              .map((t) => (
                <option key={t} value={t}>
                  {t}
                </option>
              ))}
          </select>
        }
      />
      <div
        style={{
          background: COLORS.panel2,
          border: `1px solid ${COLORS.border}`,
          borderRadius: 12,
          padding: 16,
          marginBottom: 24,
        }}
      >
        <ResponsiveContainer width="100%" height={180}>
          <BarChart
            data={cmpData}
            margin={{ top: 4, right: 20, left: -10, bottom: 0 }}
          >
            <CartesianGrid
              stroke={COLORS.border}
              strokeDasharray="3 3"
              vertical={false}
            />
            <XAxis
              dataKey="name"
              tick={{ fill: COLORS.textDim, fontSize: 11 }}
            />
            <YAxis
              domain={[0.4, 1]}
              tick={{ fill: COLORS.textFaint, fontSize: 10 }}
            />
            <Tooltip
              content={({ active, payload }) => {
                if (!active || !payload?.length) return null;
                const d = payload[0].payload;
                return (
                  <div
                    style={{
                      background: COLORS.panel3,
                      border: `1px solid ${COLORS.borderLight}`,
                      borderRadius: 8,
                      padding: "6px 10px",
                      fontSize: 12,
                      color: COLORS.text,
                    }}
                  >
                    {d.name}: AUROC {d.AUROC}
                  </div>
                );
              }}
            />
            <Bar dataKey="AUROC" radius={[6, 6, 0, 0]}>
              {cmpData.map((d, i) => (
                <Cell key={i} fill={d.fill} />
              ))}
            </Bar>
          </BarChart>
        </ResponsiveContainer>
        <div style={{ fontSize: 10.5, color: COLORS.textFaint, marginTop: 8 }}>
          Tabular models (LogReg/RF/XGBoost) use 215 features: 41 single-hour +
          174 window-summary stats (mean/std/min/max/6h-trend/24h-trend) over
          the same 24h lookback the BiLSTM sees as a raw sequence.
        </div>
      </div>

      <SectionLabel
        icon={<Activity size={13} />}
        text="Production Model (XGBoost) — All 15 Tasks"
      />
      <div
        style={{
          background: COLORS.panel2,
          border: `1px solid ${COLORS.border}`,
          borderRadius: 12,
          overflow: "hidden",
          marginBottom: 24,
        }}
      >
        <table
          style={{
            width: "100%",
            borderCollapse: "collapse",
            fontFamily: COLORS.mono,
            fontSize: 11.5,
          }}
        >
          <thead>
            <tr style={{ background: COLORS.panel3 }}>
              {[
                "Task",
                "AUROC",
                "AUPRC",
                "Precision",
                "Recall",
                "F1",
                "ECE (calibrated)",
              ].map((h) => (
                <th
                  key={h}
                  style={{
                    textAlign: "left",
                    padding: "8px 12px",
                    color: COLORS.textFaint,
                    fontWeight: 500,
                    fontSize: 10,
                    textTransform: "uppercase",
                  }}
                >
                  {h}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {taskRows.map(([name, m]) => (
              <tr
                key={name}
                style={{ borderTop: `1px solid ${COLORS.border}` }}
              >
                <td style={{ padding: "7px 12px", color: COLORS.text }}>
                  {name}
                </td>
                {m.note ? (
                  <td
                    colSpan={6}
                    style={{ padding: "7px 12px", color: COLORS.textFaint }}
                  >
                    {m.note}
                  </td>
                ) : (
                  <>
                    <td style={{ padding: "7px 12px", color: COLORS.textDim }}>
                      {m.test_AUROC}
                    </td>
                    <td style={{ padding: "7px 12px", color: COLORS.textDim }}>
                      {m.test_AUPRC}
                    </td>
                    <td style={{ padding: "7px 12px", color: COLORS.textDim }}>
                      {m.precision}
                    </td>
                    <td style={{ padding: "7px 12px", color: COLORS.textDim }}>
                      {m.recall}
                    </td>
                    <td style={{ padding: "7px 12px", color: COLORS.textDim }}>
                      {m.f1}
                    </td>
                    <td style={{ padding: "7px 12px", color: COLORS.textDim }}>
                      {m.calibration.ece_after_platt_scaling}
                    </td>
                  </>
                )}
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* ---- Concept Drift Monitoring ---- */}
      {DATA.driftReport && (
        <>
          <SectionLabel
            icon={<TrendingUp size={13} />}
            text="Concept Drift Monitoring"
          />
          <div
            style={{
              background: COLORS.panel2,
              border: `1px solid ${COLORS.border}`,
              borderRadius: 12,
              padding: 16,
              marginBottom: 24,
            }}
          >
            <div
              style={{
                display: "flex",
                alignItems: "center",
                gap: 10,
                marginBottom: 14,
                padding: "8px 12px",
                borderRadius: 8,
                background: DATA.driftReport.summary.retraining_recommended
                  ? COLORS.amberDim
                  : COLORS.greenDim,
              }}
            >
              {DATA.driftReport.summary.retraining_recommended ? (
                <AlertTriangle size={14} color={COLORS.amber} />
              ) : (
                <CheckCircle2 size={14} color={COLORS.green} />
              )}
              <span
                style={{ fontSize: 12, color: COLORS.text, fontWeight: 600 }}
              >
                {DATA.driftReport.summary.retraining_recommended
                  ? "Retraining may be needed"
                  : "No significant drift detected"}
              </span>
              <span style={{ fontSize: 11, color: COLORS.textDim }}>
                — {DATA.driftReport.summary.reason}
              </span>
            </div>
            <div
              style={{
                fontSize: 11.5,
                color: COLORS.textDim,
                fontWeight: 600,
                marginBottom: 8,
              }}
            >
              Prediction Drift by Condition (PSI)
            </div>
            <div
              style={{
                display: "grid",
                gridTemplateColumns: "repeat(5, 1fr)",
                gap: 8,
                marginBottom: 16,
              }}
            >
              {CONDITIONS.map((c) => {
                const d = DATA.driftReport.predictionDrift[c];
                if (!d) return null;
                const col =
                  d.drift_status === "no_drift"
                    ? COLORS.green
                    : d.drift_status === "moderate_drift"
                      ? COLORS.amber
                      : COLORS.red;
                return (
                  <div
                    key={c}
                    style={{
                      background: COLORS.panel3,
                      borderRadius: 8,
                      padding: "8px 10px",
                      border: `1px solid ${COLORS.border}`,
                    }}
                  >
                    <div
                      style={{
                        fontSize: 11,
                        color: CONDITION_META[c].color,
                        fontWeight: 600,
                      }}
                    >
                      {c}
                    </div>
                    <div
                      style={{
                        fontSize: 18,
                        fontWeight: 700,
                        color: col,
                        fontFamily: COLORS.mono,
                      }}
                    >
                      {d.prediction_psi.toFixed(3)}
                    </div>
                    <div style={{ fontSize: 9.5, color: COLORS.textFaint }}>
                      train: {(d.train_mean_risk * 100).toFixed(1)}% → test:{" "}
                      {(d.test_mean_risk * 100).toFixed(1)}%
                    </div>
                  </div>
                );
              })}
            </div>
            <div
              style={{
                fontSize: 11.5,
                color: COLORS.textDim,
                fontWeight: 600,
                marginBottom: 8,
              }}
            >
              Temporal Windows
            </div>
            <div
              style={{
                display: "grid",
                gridTemplateColumns: "repeat(4, 1fr)",
                gap: 8,
              }}
            >
              {(DATA.driftReport.temporalWindows || []).map((w, i) => (
                <div
                  key={i}
                  style={{
                    background: COLORS.panel3,
                    borderRadius: 8,
                    padding: "8px 10px",
                    border: `1px solid ${COLORS.border}`,
                  }}
                >
                  <div
                    style={{
                      fontSize: 11,
                      color: COLORS.text,
                      fontWeight: 600,
                    }}
                  >
                    Window {w.window}
                  </div>
                  <div style={{ fontSize: 10, color: COLORS.textFaint }}>
                    {w.n_patients} patients · {w.n_features_drifted} features
                    drifted
                  </div>
                  <div
                    style={{
                      display: "flex",
                      gap: 4,
                      marginTop: 4,
                      flexWrap: "wrap",
                    }}
                  >
                    {CONDITIONS.map((c) => (
                      <span
                        key={c}
                        style={{
                          fontSize: 9,
                          padding: "1px 4px",
                          borderRadius: 3,
                          background: COLORS.panel2,
                          color: CONDITION_META[c].color,
                        }}
                      >
                        {c}:{" "}
                        {((w.mean_risk_by_condition[c] || 0) * 100).toFixed(0)}%
                      </span>
                    ))}
                  </div>
                </div>
              ))}
            </div>
          </div>
        </>
      )}

      {/* ---- Surrogate Fidelity Summary ---- */}
      {DATA.surrogateFidelity && (
        <>
          <SectionLabel
            icon={<Search size={13} />}
            text="Surrogate Fidelity Summary (linear simulator vs XGBoost)"
          />
          <div
            style={{
              background: COLORS.panel2,
              border: `1px solid ${COLORS.border}`,
              borderRadius: 12,
              padding: 16,
              marginBottom: 24,
            }}
          >
            <div
              style={{
                display: "grid",
                gridTemplateColumns: "repeat(5, 1fr)",
                gap: 8,
              }}
            >
              {CONDITIONS.map((c) => {
                const f = DATA.surrogateFidelity[c];
                if (!f) return null;
                return (
                  <div
                    key={c}
                    style={{
                      background: COLORS.panel3,
                      borderRadius: 8,
                      padding: "8px 10px",
                      border: `1px solid ${COLORS.border}`,
                    }}
                  >
                    <div
                      style={{
                        fontSize: 11,
                        color: CONDITION_META[c].color,
                        fontWeight: 600,
                        marginBottom: 4,
                      }}
                    >
                      {c}
                    </div>
                    <div style={{ fontSize: 10, color: COLORS.textDim }}>
                      MAE:{" "}
                      <span
                        style={{ fontFamily: COLORS.mono, color: COLORS.text }}
                      >
                        {f.overall.mae.toFixed(3)}
                      </span>
                    </div>
                    <div style={{ fontSize: 10, color: COLORS.textDim }}>
                      Correlation:{" "}
                      <span
                        style={{ fontFamily: COLORS.mono, color: COLORS.text }}
                      >
                        {f.overall.pearson_r.toFixed(3)}
                      </span>
                    </div>
                    <div style={{ fontSize: 10, color: COLORS.textDim }}>
                      Agreement:{" "}
                      <span
                        style={{ fontFamily: COLORS.mono, color: COLORS.text }}
                      >
                        {(f.overall["agreement_at_0.5"] * 100).toFixed(1)}%
                      </span>
                    </div>
                    {f.unreliable_regions &&
                      f.unreliable_regions.length > 0 && (
                        <div
                          style={{
                            fontSize: 9,
                            color: COLORS.amber,
                            marginTop: 4,
                          }}
                        >
                          Diverges on:{" "}
                          {f.unreliable_regions
                            .slice(0, 2)
                            .map((r) => r.feature)
                            .join(", ")}
                        </div>
                      )}
                  </div>
                );
              })}
            </div>
          </div>
        </>
      )}

      {/* ---- OOD Distribution Summary ---- */}
      {DATA.oodSummary && (
        <>
          <SectionLabel
            icon={<ShieldAlert size={13} />}
            text="Out-of-Distribution Detection Summary"
          />
          <div
            style={{
              background: COLORS.panel2,
              border: `1px solid ${COLORS.border}`,
              borderRadius: 12,
              padding: 16,
              marginBottom: 24,
            }}
          >
            <div style={{ display: "flex", gap: 20 }}>
              <div>
                <div style={{ fontSize: 10.5, color: COLORS.textFaint }}>
                  Training samples
                </div>
                <div
                  style={{
                    fontSize: 16,
                    fontWeight: 700,
                    color: COLORS.text,
                    fontFamily: COLORS.mono,
                  }}
                >
                  {DATA.oodSummary.trainingStats.n_train_samples.toLocaleString()}
                </div>
              </div>
              <div>
                <div style={{ fontSize: 10.5, color: COLORS.textFaint }}>
                  Test patients
                </div>
                <div
                  style={{
                    fontSize: 16,
                    fontWeight: 700,
                    color: COLORS.text,
                    fontFamily: COLORS.mono,
                  }}
                >
                  {DATA.oodSummary.testDistribution.n_patients}
                </div>
              </div>
              <div>
                <div style={{ fontSize: 10.5, color: COLORS.textFaint }}>
                  Borderline (%)
                </div>
                <div
                  style={{
                    fontSize: 16,
                    fontWeight: 700,
                    color: COLORS.amber,
                    fontFamily: COLORS.mono,
                  }}
                >
                  {DATA.oodSummary.testDistribution.pct_borderline}%
                </div>
              </div>
              <div>
                <div style={{ fontSize: 10.5, color: COLORS.textFaint }}>
                  Out-of-distribution (%)
                </div>
                <div
                  style={{
                    fontSize: 16,
                    fontWeight: 700,
                    color: COLORS.red,
                    fontFamily: COLORS.mono,
                  }}
                >
                  {DATA.oodSummary.testDistribution.pct_ood}%
                </div>
              </div>
            </div>
            <div
              style={{ fontSize: 10, color: COLORS.textFaint, marginTop: 10 }}
            >
              Mahalanobis distance thresholds — p90:{" "}
              {DATA.oodSummary.trainingStats.percentiles.p90.toFixed(1)}, p95:{" "}
              {DATA.oodSummary.trainingStats.percentiles.p95.toFixed(1)}, p99:{" "}
              {DATA.oodSummary.trainingStats.percentiles.p99.toFixed(1)}
            </div>
          </div>
        </>
      )}
    </div>
  );
}

/* ================= audit log ================= */

function AuditLogView({ log }) {
  const exportLog = () => {
    const rows = [["timestamp", "event", "detail"]];
    log.forEach((e) => rows.push([e.time, e.event, e.detail]));
    downloadCSV("audit_log.csv", rows);
  };
  return (
    <div style={{ padding: 24, overflowY: "auto", flex: 1 }}>
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          marginBottom: 18,
        }}
      >
        <div>
          <div style={{ fontSize: 18, fontWeight: 700 }}>Audit Log</div>
          <div style={{ fontSize: 12, color: COLORS.textFaint, marginTop: 2 }}>
            Session-local event trail — logins, patient views, simulation runs
          </div>
        </div>
        <GhostButton onClick={exportLog} icon={<Download size={12} />}>
          Export CSV
        </GhostButton>
      </div>
      <div
        style={{
          background: COLORS.panel2,
          border: `1px solid ${COLORS.border}`,
          borderRadius: 12,
          overflow: "hidden",
        }}
      >
        {log.length === 0 ? (
          <div
            style={{
              padding: 24,
              color: COLORS.textFaint,
              fontSize: 12,
              textAlign: "center",
            }}
          >
            No events yet this session.
          </div>
        ) : (
          [...log].reverse().map((e, i) => (
            <div
              key={i}
              style={{
                display: "flex",
                gap: 14,
                padding: "10px 16px",
                borderTop: i ? `1px solid ${COLORS.border}` : "none",
                fontSize: 12,
              }}
            >
              <span
                style={{
                  fontFamily: COLORS.mono,
                  color: COLORS.textFaint,
                  minWidth: 84,
                }}
              >
                {e.time}
              </span>
              <span
                style={{
                  fontFamily: COLORS.mono,
                  color: COLORS.blue,
                  minWidth: 110,
                }}
              >
                {e.event}
              </span>
              <span style={{ color: COLORS.textDim }}>{e.detail}</span>
            </div>
          ))
        )}
      </div>
    </div>
  );
}

/* ================= app shell ================= */

function MetricBadge({ label, value }) {
  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        alignItems: "flex-end",
      }}
    >
      <span style={{ color: COLORS.textFaint, fontSize: 9 }}>{label}</span>
      <span style={{ color: COLORS.text, fontWeight: 600 }}>{value}</span>
    </div>
  );
}

export default function ICUDigitalTwinDashboard() {
  const [user, setUser] = useState(null);
  const [view, setView] = useState("console");
  const [selectedId, setSelectedId] = useState(DATA.patients[0].patientId);
  const [search, setSearch] = useState("");
  const [log, setLog] = useState([]);
  const [replayHour, setReplayHour] = useState(0);
  const [replayResult, setReplayResult] = useState(null);
  const [replayLoading, setReplayLoading] = useState(false);
  const [replayError, setReplayError] = useState("");
  const [observations, setObservations] = useState(null);
  const [observationsError, setObservationsError] = useState("");
  const [xaiTask, setXaiTask] = useState("Sepsis_6h");
  const [xaiResult, setXaiResult] = useState(null);
  const [xaiLoading, setXaiLoading] = useState(false);
  const [xaiError, setXaiError] = useState("");
  const [availableHours, setAvailableHours] = useState([]);
  const [isPlaying, setIsPlaying] = useState(false);

  const [scenarioChanges, setScenarioChanges] = useState({
    HR: "",
    SBP: "",
    Resp: "",
    TempC: "",
    FiO2: "",
  });
  const [scenarioResult, setScenarioResult] = useState(null);
  const [scenarioLoading, setScenarioLoading] = useState(false);
  const [scenarioError, setScenarioError] = useState("");

  useEffect(() => {
    const loadAvailableHours = async () => {
      try {
        const response = await fetch(`${API_URL}/mimic/hours`);
        const data = await response.json();

        if (!response.ok) {
          throw new Error(data.detail || "Could not load available hours");
        }

        setAvailableHours(data.hours || []);
      } catch (error) {
        setReplayError(error.message || "Could not load available hours");
      }
    };

    loadAvailableHours();
  }, []);

  const addLog = useCallback(
    (event, detail) =>
      setLog((l) => [
        ...l,
        { time: new Date().toLocaleTimeString(), event, detail },
      ]),
    [],
  );
  const handleLogin = (u) => {
    setUser(u);
    addLog("login", `${u.name} signed in as ${u.role}`);
  };
  const handleSelectPatient = (pid) => {
    setSelectedId(pid);
    addLog("view_patient", pid);
  };
  const runReplayHour = useCallback(
    async (hour) => {
      setReplayLoading(true);
      setReplayError("");

      try {
        const response = await fetch(`${API_URL}/mimic/predict-hour/${hour}`);
        const data = await response.json();

        if (!response.ok) {
          throw new Error(data.detail || "Replay prediction failed");
        }

        setReplayHour(hour);
        setReplayResult(data);
        const obsResponse = await fetch(
          `${API_URL}/mimic/observations/${hour}`,
        );
        const obsData = await obsResponse.json();

        if (!obsResponse.ok) {
          throw new Error(obsData.detail || "Could not load observations");
        }

        setObservations(obsData.observations);
        setObservationsError("");
        addLog("mimic_replay", `Hour ${hour} · ${data.model_version}`);
      } catch (error) {
        setReplayError(error.message || "Could not load replay predictions");
        setObservationsError(error.message || "Could not load observations");
      } finally {
        setReplayLoading(false);
      }
    },
    [addLog],
  );

  useEffect(() => {
    if (!isPlaying || replayLoading || availableHours.length === 0) {
      return;
    }

    const currentIndex = availableHours.indexOf(replayHour);
    const nextIndex = currentIndex + 1;

    if (currentIndex === -1 || nextIndex >= availableHours.length) {
      setIsPlaying(false);
      return;
    }

    const timer = setTimeout(() => {
      runReplayHour(availableHours[nextIndex]);
    }, 2000);

    return () => clearTimeout(timer);
  }, [isPlaying, replayLoading, replayHour, availableHours, runReplayHour]);

  const explainPrediction = async () => {
    setXaiLoading(true);
    setXaiError("");
    setXaiResult(null);

    try {
      const response = await fetch(
        `${API_URL}/mimic/explain-hour/${replayHour}/${xaiTask}`,
      );
      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.detail || "Could not explain prediction");
      }

      setXaiResult(data);
    } catch (error) {
      setXaiError(error.message || "Could not load explanation");
    } finally {
      setXaiLoading(false);
    }
  };

  const runScenario = async () => {
    const changes = Object.fromEntries(
      Object.entries(scenarioChanges)
        .filter(([, value]) => value !== "")
        .map(([key, value]) => [key, Number(value)]),
    );

    if (Object.keys(changes).length === 0) {
      setScenarioError("Enter at least one value to simulate.");
      return;
    }

    setScenarioLoading(true);
    setScenarioError("");
    setScenarioResult(null);

    try {
      const response = await fetch(`${API_URL}/mimic/scenario`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ hour: replayHour, changes }),
      });

      const data = await response.json();

      if (!response.ok) {
        const detail = Array.isArray(data.detail)
          ? data.detail.map((item) => item.msg).join("; ")
          : data.detail;
        throw new Error(detail || "Scenario simulation failed");
      }

      setScenarioResult(data);
      addLog(
        "mimic_scenario",
        `Hour ${replayHour} · ${Object.entries(changes)
          .map(([k, v]) => `${k}=${v}`)
          .join(", ")}`,
      );
    } catch (error) {
      setScenarioError(error.message || "Scenario simulation failed");
    } finally {
      setScenarioLoading(false);
    }
  };

  const handleRunAudit = (condition, overrides, risk) => {
    const desc =
      Object.entries(overrides)
        .map(([k, v]) => `${k}=${v}`)
        .join(", ") || "no overrides (baseline)";
    addLog(
      "simulation_run",
      `${selectedId} · ${condition} · ${desc} · risk=${(risk * 100).toFixed(1)}%`,
    );
  };

  if (!user) return <LoginScreen onLogin={handleLogin} />;

  const patient = DATA.patients.find((p) => p.patientId === selectedId);
  const canSeeResearch = user.role === "researcher" || user.role === "admin";
  const canSeeAudit = user.role === "admin";

  const NAV = [
    { id: "console", label: "Console", icon: LayoutGrid, show: true },
    {
      id: "cohort",
      label: "Cohort Analytics",
      icon: BarChart3,
      show: canSeeResearch,
    },
    { id: "audit", label: "Audit Log", icon: ScrollText, show: canSeeAudit },

    { id: "mimic", label: "MIMIC-IV Twin", icon: Activity, show: true },
  ];

  return (
    <div
      style={{
        background: COLORS.bg,
        color: COLORS.text,
        fontFamily: COLORS.sans,
        display: "flex",
        flexDirection: "column",
        height: "100vh",
        minHeight: 640,
      }}
    >
      <div
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          padding: "10px 20px",
          borderBottom: `1px solid ${COLORS.border}`,
          background: COLORS.panel,
          flexShrink: 0,
        }}
      >
        <div style={{ display: "flex", alignItems: "center", gap: 22 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
            <HeartPulse size={19} color={COLORS.blue} />
            <div>
              <div style={{ fontSize: 14, fontWeight: 700 }}>ICU-DT</div>
              <div
                style={{ fontSize: 10, color: COLORS.textFaint, marginTop: -2 }}
              >
                Production: XGBoost+RF Ensemble · Explained via exact SHAP
              </div>
            </div>
          </div>
          <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
            <div
              style={{
                padding: "3px 8px",
                background: COLORS.blueDim,
                borderRadius: 6,
                fontSize: 10,
                color: COLORS.blue,
                fontWeight: 600,
              }}
            >
              v1.0-pub
            </div>
            <div
              title="ARF, Cardiac, AKI, Coagulopathy use rule-based proxy labels, not adjudicated ground truth. Only SepsisLabel is expert-annotated."
              style={{
                padding: "3px 8px",
                background: COLORS.amberDim,
                borderRadius: 6,
                fontSize: 10,
                color: COLORS.amber,
                fontWeight: 600,
                cursor: "help",
              }}
            >
              Proxy Labels
            </div>
          </div>
          <div style={{ display: "flex", gap: 4 }}>
            {NAV.filter((n) => n.show).map((n) => {
              const Icon = n.icon;
              const active = view === n.id;
              return (
                <button
                  key={n.id}
                  onClick={() => setView(n.id)}
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: 6,
                    cursor: "pointer",
                    padding: "6px 12px",
                    borderRadius: 7,
                    background: active ? COLORS.panel2 : "transparent",
                    border: "none",
                    color: active ? COLORS.text : COLORS.textFaint,
                    fontSize: 12.5,
                  }}
                >
                  <Icon size={13} />
                  {n.label}
                </button>
              );
            })}
          </div>
        </div>
        <div style={{ display: "flex", gap: 18, alignItems: "center" }}>
          <div
            style={{
              display: "flex",
              gap: 14,
              fontFamily: COLORS.mono,
              fontSize: 11,
            }}
          >
            {CONDITIONS.map((c) => (
              <MetricBadge
                key={c}
                label={c.toUpperCase()}
                value={DATA.modelMetrics[`${c}_6h`]?.test_AUROC ?? "—"}
              />
            ))}
          </div>
          <div style={{ width: 1, height: 24, background: COLORS.border }} />
          <div style={{ textAlign: "right" }}>
            <div style={{ fontSize: 12, fontWeight: 600 }}>{user.name}</div>
            <div
              style={{
                fontSize: 10,
                color: COLORS.textFaint,
                textTransform: "capitalize",
              }}
            >
              {user.role}
            </div>
          </div>
          <button
            onClick={() => {
              addLog("logout", user.name);
              setUser(null);
            }}
            style={{
              background: "transparent",
              border: "none",
              cursor: "pointer",
              color: COLORS.textFaint,
            }}
          >
            <LogOut size={16} />
          </button>
        </div>
      </div>

      {view === "mimic" && (
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: 12,
            padding: "10px 20px",
            background: COLORS.panel,
            borderBottom: `1px solid ${COLORS.border}`,
            flexShrink: 0,
          }}
        >
          <div style={{ fontSize: 12, fontWeight: 700 }}>MIMIC-IV Replay</div>

          <label style={{ fontSize: 12 }}>Hour</label>

          <input
            type="number"
            min="0"
            max="488"
            value={replayHour}
            onChange={(e) => {
              const value = Number(e.target.value);
              if (Number.isInteger(value) && value >= 0 && value <= 488) {
                setReplayHour(value);
              }
            }}
            style={{
              width: 75,
              padding: "6px 8px",
              borderRadius: 6,
              border: `1px solid ${COLORS.border}`,
              background: COLORS.bg,
              color: COLORS.text,
            }}
          />

          <button
            onClick={() => runReplayHour(replayHour)}
            disabled={replayLoading}
            style={{
              padding: "7px 12px",
              borderRadius: 6,
              border: "none",
              background: COLORS.blue,
              color: "#fff",
              cursor: replayLoading ? "wait" : "pointer",
              opacity: replayLoading ? 0.6 : 1,
            }}
          >
            {replayLoading ? "Predicting..." : "Run Hour"}
          </button>

          <button
            onClick={() => {
              const index = availableHours.indexOf(replayHour);
              if (index > 0) runReplayHour(availableHours[index - 1]);
            }}
            disabled={replayLoading || availableHours.indexOf(replayHour) <= 0}
            style={{
              padding: "7px 12px",
              borderRadius: 6,
              border: `1px solid ${COLORS.border}`,
              background: COLORS.panel,
              color: COLORS.text,
              cursor: "pointer",
            }}
          >
            Previous
          </button>

          <button
            onClick={() => setIsPlaying((playing) => !playing)}
            disabled={availableHours.length === 0 || replayLoading}
            style={{
              padding: "7px 12px",
              borderRadius: 6,
              border: "none",
              background: COLORS.blue,
              color: "#fff",
              cursor: "pointer",
            }}
          >
            {isPlaying ? "Pause" : "Play"}
          </button>

          <button
            onClick={() => {
              const index = availableHours.indexOf(replayHour);
              if (index >= 0 && index < availableHours.length - 1) {
                runReplayHour(availableHours[index + 1]);
              }
            }}
            disabled={
              replayLoading ||
              availableHours.indexOf(replayHour) === -1 ||
              availableHours.indexOf(replayHour) >= availableHours.length - 1
            }
            style={{
              padding: "7px 12px",
              borderRadius: 6,
              border: `1px solid ${COLORS.border}`,
              background: COLORS.panel,
              color: COLORS.text,
              cursor: "pointer",
            }}
          >
            Next
          </button>

          {replayError && (
            <span style={{ fontSize: 11, color: COLORS.amber }}>
              {replayError}
            </span>
          )}
        </div>
      )}

      {view === "mimic" && (
        <div
          style={{
            flex: "0 0 auto",
            minHeight: "auto",
            overflowY: "visible",
            padding: 20,
            background: COLORS.bg,
            color: COLORS.text,
          }}
        >
          <div
            style={{
              fontSize: 18,
              fontWeight: 700,
              marginBottom: 16,
            }}
          >
            Patient Observations — Hour {replayHour}
          </div>

          {!observations ? (
            <div
              style={{
                padding: 20,
                border: `1px solid ${COLORS.border}`,
                borderRadius: 12,
                background: COLORS.panel,
                color: COLORS.textFaint,
              }}
            >
              {observationsError ||
                "Select an hour and click Run Hour to load observations."}
            </div>
          ) : (
            <div
              style={{
                padding: 20,
                border: `1px solid ${COLORS.border}`,
                borderRadius: 12,
                background: COLORS.panel,
              }}
            >
              <div style={{ fontSize: 14, fontWeight: 600 }}>
                Observations — Hour {replayHour}
              </div>

              <div
                style={{
                  display: "grid",
                  gridTemplateColumns: "repeat(auto-fit, minmax(130px, 1fr))",
                  gap: 12,
                  marginTop: 16,
                }}
              >
                {[
                  ["Heart Rate", "HR", "bpm"],
                  ["Systolic BP", "SBP", "mmHg"],
                  ["Diastolic BP", "DBP", "mmHg"],
                  ["Mean Arterial Pressure", "MAP", "mmHg"],
                  ["Respiratory Rate", "Resp", "/min"],
                  ["Temperature", "TempC", "°C"],
                  ["Oxygen Saturation", "O2Sat", "%"],
                  ["FiO₂", "FiO2", ""],
                  ["pH", "pH", ""],
                  ["PaCO₂", "PaCO2", "mmHg"],
                  ["Lactate", "Lactate", "mmol/L"],
                  ["Creatinine", "Creatinine", "mg/dL"],
                  ["BUN", "BUN", "mg/dL"],
                  ["WBC", "WBC", ""],
                  ["Platelets", "Platelets", ""],
                  ["Glucose", "Glucose", "mg/dL"],
                ].map(([label, key, unit]) => (
                  <div
                    key={key}
                    style={{
                      padding: 12,
                      border: `1px solid ${COLORS.border}`,
                      borderRadius: 8,
                      background: COLORS.bg,
                    }}
                  >
                    <div style={{ fontSize: 11, color: COLORS.textFaint }}>
                      {label}
                    </div>
                    <div
                      style={{ fontSize: 18, fontWeight: 700, marginTop: 5 }}
                    >
                      {observations[key] == null
                        ? "N/A"
                        : `${Number(observations[key]).toFixed(1)} ${unit}`}
                    </div>
                  </div>
                ))}
              </div>

              <div
                style={{
                  fontSize: 11,
                  color: COLORS.textFaint,
                  marginTop: 16,
                }}
              ></div>
            </div>
          )}
        </div>
      )}

      {view === "mimic" && replayResult && (
        <div
          style={{
            padding: "12px 20px",
            background: COLORS.panel,
            borderBottom: `1px solid ${COLORS.border}`,
            display: "grid",
            gridTemplateColumns: "repeat(5, minmax(0, 1fr))",
            gap: 12,
            flexShrink: 0,
          }}
        >
          {[
            ["Sepsis", "Sepsis"],
            ["ARF", "ARF"],
            ["Cardiac", "Cardiac"],
            ["AKI", "AKI"],
            ["Coagulopathy", "Coagulopathy"],
          ].map(([label, prefix]) => (
            <div
              key={prefix}
              style={{
                padding: 10,
                border: `1px solid ${COLORS.border}`,
                borderRadius: 8,
                background: COLORS.bg,
              }}
            >
              <div
                style={{
                  fontSize: 12,
                  fontWeight: 700,
                  marginBottom: 8,
                }}
              >
                {label}
              </div>

              {[6, 12, 24].map((horizon) => {
                const score = replayResult.tasks[`${prefix}_${horizon}h_score`];

                return (
                  <div
                    key={horizon}
                    style={{
                      display: "flex",
                      justifyContent: "space-between",
                      gap: 8,
                      fontSize: 11,
                      marginTop: 5,
                    }}
                  >
                    <span style={{ color: COLORS.textFaint }}>{horizon}h</span>
                    <span style={{ fontFamily: COLORS.mono }}>
                      {typeof score === "number"
                        ? `${(score * 100).toFixed(1)}%`
                        : "—"}
                    </span>
                  </div>
                );
              })}
            </div>
          ))}
        </div>
      )}
      {view === "mimic" && replayResult && (
        <div
          style={{
            margin: 20,
            padding: 20,
            background: COLORS.panel,
            border: `1px solid ${COLORS.border}`,
            borderRadius: 12,
          }}
        >
          <div style={{ fontSize: 18, fontWeight: 700 }}>
            Explainable AI — Why This Prediction?
          </div>

          <div
            style={{
              display: "flex",
              gap: 12,
              alignItems: "center",
              marginTop: 14,
              flexWrap: "wrap",
            }}
          >
            <label style={{ fontSize: 12 }}>
              Prediction to explain
              <select
                value={xaiTask}
                onChange={(e) => {
                  setXaiTask(e.target.value);
                  setXaiResult(null);
                  setXaiError("");
                }}
                style={{
                  display: "block",
                  marginTop: 6,
                  padding: 9,
                  borderRadius: 6,
                  border: `1px solid ${COLORS.border}`,
                  background: COLORS.bg,
                  color: COLORS.text,
                }}
              >
                {[
                  "Sepsis_6h",
                  "Sepsis_12h",
                  "Sepsis_24h",
                  "ARF_6h",
                  "ARF_12h",
                  "ARF_24h",
                  "Cardiac_6h",
                  "Cardiac_12h",
                  "Cardiac_24h",
                  "AKI_6h",
                  "AKI_12h",
                  "AKI_24h",
                  "Coagulopathy_6h",
                  "Coagulopathy_12h",
                  "Coagulopathy_24h",
                ].map((task) => (
                  <option key={task} value={task}>
                    {task.replace("_", " · ")}
                  </option>
                ))}
              </select>
            </label>

            <button
              onClick={explainPrediction}
              disabled={xaiLoading}
              style={{
                padding: "9px 14px",
                marginTop: 18,
                border: "none",
                borderRadius: 6,
                background: COLORS.blue,
                color: "#fff",
                cursor: xaiLoading ? "wait" : "pointer",
              }}
            >
              {xaiLoading ? "Explaining..." : "Explain Prediction"}
            </button>
          </div>

          {xaiError && (
            <div style={{ color: COLORS.amber, fontSize: 12, marginTop: 12 }}>
              {xaiError}
            </div>
          )}

          {xaiResult && (
            <div style={{ marginTop: 20 }}>
              <div style={{ fontSize: 14, fontWeight: 700 }}>
                {xaiResult.task.replace("_", " · ")} — Hour {xaiResult.hour}
              </div>

              <div style={{ fontSize: 12, marginTop: 8 }}>
                Model prediction:{" "}
                <strong>{(xaiResult.prediction * 100).toFixed(1)}%</strong>
              </div>

              <div
                style={{
                  fontSize: 12,
                  color: COLORS.textFaint,
                  marginTop: 10,
                  marginBottom: 14,
                }}
              >
                SHAP contributions show which features pushed the model output
                higher or lower. They are not percentage-point changes in risk.
              </div>

              <div style={{ display: "grid", gap: 10 }}>
                {xaiResult.features.map((item) => (
                  <div
                    key={item.feature}
                    style={{
                      display: "grid",
                      gridTemplateColumns:
                        "minmax(120px, 1fr) minmax(80px, 2fr) 90px",
                      gap: 10,
                      alignItems: "center",
                      fontSize: 12,
                    }}
                  >
                    <span>{item.feature}</span>

                    <div
                      style={{
                        height: 12,
                        borderRadius: 4,
                        background: COLORS.bg,
                        overflow: "hidden",
                      }}
                    >
                      <div
                        title={`SHAP contribution: ${item.contribution.toFixed(4)}`}
                        style={{
                          width: `${Math.min(100, Math.abs(item.contribution) * 100)}%`,
                          height: "100%",
                          background:
                            item.contribution >= 0 ? COLORS.amber : COLORS.blue,
                          borderRadius: 4,
                        }}
                      />
                    </div>

                    <span
                      style={{ fontFamily: COLORS.mono, textAlign: "right" }}
                    >
                      {item.contribution > 0 ? "+" : ""}
                      {item.contribution.toFixed(4)}
                    </span>
                  </div>
                ))}
              </div>

              <div
                style={{
                  fontSize: 11,
                  color: COLORS.textFaint,
                  marginTop: 16,
                }}
              >
                {xaiResult.interpretation}
              </div>
            </div>
          )}
        </div>
      )}

      {view === "mimic" && (
        <div style={{ padding: 20, background: COLORS.bg, color: COLORS.text }}>
          <div
            style={{
              padding: 20,
              border: `1px solid ${COLORS.border}`,
              borderRadius: 12,
              background: COLORS.panel,
            }}
          >
            <div style={{ fontSize: 18, fontWeight: 700 }}>
              Scenario Simulation
            </div>
            <div
              style={{ fontSize: 12, color: COLORS.textFaint, marginTop: 6 }}
            >
              Hour {replayHour} · Exploratory what-if simulation
            </div>

            <div
              style={{
                display: "grid",
                gridTemplateColumns: "repeat(auto-fit, minmax(130px, 1fr))",
                gap: 12,
                marginTop: 16,
              }}
            >
              {[
                ["HR", "Heart rate", "20", "250", "77"],
                ["SBP", "Systolic BP", "40", "300", "100"],
                ["Resp", "Respiratory rate", "1", "80", "18"],
                ["TempC", "Temperature (°C)", "25", "45", "37"],
                ["FiO2", "FiO₂ fraction", "0.21", "1", "0.4"],
              ].map(([key, label, min, max, placeholder]) => (
                <label key={key} style={{ fontSize: 12 }}>
                  {label}
                  <input
                    type="number"
                    min={min}
                    max={max}
                    step="any"
                    placeholder={placeholder}
                    value={scenarioChanges[key]}
                    onChange={(e) =>
                      setScenarioChanges((prev) => ({
                        ...prev,
                        [key]: e.target.value,
                      }))
                    }
                    style={{
                      display: "block",
                      boxSizing: "border-box",
                      width: "100%",
                      marginTop: 6,
                      padding: 9,
                      borderRadius: 6,
                      border: `1px solid ${COLORS.border}`,
                      background: COLORS.bg,
                      color: COLORS.text,
                    }}
                  />
                </label>
              ))}
            </div>

            <div style={{ display: "flex", gap: 10, marginTop: 16 }}>
              <button
                onClick={runScenario}
                disabled={scenarioLoading}
                style={{
                  padding: "9px 14px",
                  border: "none",
                  borderRadius: 6,
                  background: COLORS.blue,
                  color: "#fff",
                  cursor: scenarioLoading ? "wait" : "pointer",
                }}
              >
                {scenarioLoading ? "Simulating..." : "Run Scenario"}
              </button>

              <button
                onClick={() => {
                  setScenarioChanges({
                    HR: "",
                    SBP: "",
                    Resp: "",
                    TempC: "",
                    FiO2: "",
                  });
                  setScenarioResult(null);
                  setScenarioError("");
                }}
                style={{
                  padding: "9px 14px",
                  border: `1px solid ${COLORS.border}`,
                  borderRadius: 6,
                  background: COLORS.panel,
                  color: COLORS.text,
                  cursor: "pointer",
                }}
              >
                Reset
              </button>
            </div>

            {scenarioError && (
              <div style={{ color: COLORS.amber, fontSize: 12, marginTop: 12 }}>
                {scenarioError}
              </div>
            )}

            {scenarioResult && (
              <div style={{ marginTop: 20 }}>
                <div
                  style={{ fontSize: 14, fontWeight: 700, marginBottom: 10 }}
                >
                  Baseline vs Scenario — Hour {scenarioResult.hour}
                </div>

                {/* Baseline vs Scenario visual comparison */}
                <div style={{ marginBottom: 24 }}>
                  <div
                    style={{
                      display: "flex",
                      gap: 18,
                      alignItems: "center",
                      fontSize: 12,
                      marginBottom: 16,
                      flexWrap: "wrap",
                    }}
                  >
                    <span
                      style={{ display: "flex", alignItems: "center", gap: 7 }}
                    >
                      <span
                        style={{
                          width: 12,
                          height: 12,
                          borderRadius: 3,
                          background: COLORS.blue,
                        }}
                      />
                      Baseline
                    </span>
                    <span
                      style={{ display: "flex", alignItems: "center", gap: 7 }}
                    >
                      <span
                        style={{
                          width: 12,
                          height: 12,
                          borderRadius: 3,
                          background: COLORS.amber,
                        }}
                      />
                      Scenario
                    </span>
                  </div>

                  <div style={{ display: "grid", gap: 14 }}>
                    {Object.keys(scenarioResult.baseline_scores).map((key) => {
                      const baseline = scenarioResult.baseline_scores[key];
                      const scenario = scenarioResult.scenario_scores[key];
                      const label = key
                        .replace("_score", "")
                        .replaceAll("_", " ");

                      return (
                        <div key={key}>
                          <div
                            style={{
                              display: "flex",
                              justifyContent: "space-between",
                              alignItems: "center",
                              gap: 10,
                              fontSize: 12,
                              color: COLORS.text,
                              marginBottom: 6,
                              fontWeight: 600,
                              flexWrap: "wrap",
                            }}
                          >
                            <span>{label}</span>
                            <span
                              style={{
                                color:
                                  scenario > baseline
                                    ? COLORS.amber
                                    : scenario < baseline
                                      ? COLORS.blue
                                      : COLORS.textFaint,
                                fontFamily: COLORS.mono,
                                fontSize: 11,
                              }}
                            >
                              Change: {scenario > baseline ? "+" : ""}
                              {((scenario - baseline) * 100).toFixed(2)} pp
                            </span>
                          </div>

                          {[
                            {
                              name: "Baseline",
                              value: baseline,
                              color: COLORS.blue,
                            },
                            {
                              name: "Scenario",
                              value: scenario,
                              color: COLORS.amber,
                            },
                          ].map((item) => (
                            <div
                              key={item.name}
                              style={{
                                display: "grid",
                                gridTemplateColumns: "70px minmax(0, 1fr) 55px",
                                alignItems: "center",
                                gap: 8,
                                marginTop: 4,
                              }}
                            >
                              <span
                                style={{
                                  fontSize: 10,
                                  color: COLORS.textFaint,
                                }}
                              >
                                {item.name}
                              </span>

                              <div
                                style={{
                                  height: 12,
                                  borderRadius: 4,
                                  background: COLORS.bg,
                                  overflow: "hidden",
                                }}
                              >
                                <div
                                  title={`${item.name}: ${(item.value * 100).toFixed(2)}%`}
                                  style={{
                                    width: `${Math.max(0, Math.min(100, item.value * 100))}%`,
                                    height: "100%",
                                    borderRadius: 4,
                                    background: item.color,
                                    transition: "width 0.3s ease",
                                  }}
                                />
                              </div>

                              <span
                                style={{
                                  fontSize: 11,
                                  fontFamily: COLORS.mono,
                                  textAlign: "right",
                                }}
                              >
                                {(item.value * 100).toFixed(2)}%
                              </span>
                            </div>
                          ))}
                        </div>
                      );
                    })}
                  </div>
                </div>

                <div
                  style={{
                    fontSize: 11,
                    color: COLORS.textFaint,
                    marginTop: 12,
                  }}
                ></div>
              </div>
            )}
          </div>
        </div>
      )}

      {view === "console" && (
        <div style={{ display: "flex", flex: 1, minHeight: 0 }}>
          <Sidebar
            patients={DATA.patients}
            selectedId={selectedId}
            onSelect={handleSelectPatient}
            search={search}
            setSearch={setSearch}
          />
          {patient && (
            <PatientDetail
              patient={patient}
              onRunAudit={handleRunAudit}
              onSelectPatient={handleSelectPatient}
            />
          )}
        </div>
      )}
      {view === "cohort" && canSeeResearch && <CohortAnalyticsView />}
      {view === "audit" && canSeeAudit && <AuditLogView log={log} />}
    </div>
  );
}
